<script lang="ts">
 import {untrack} from 'svelte';import Modal from './Modal.svelte';import Feedback from './Feedback.svelte';import {Button} from '#lib/components/ui/button/index.ts';import {adminClinicsApi} from '#lib/api/admin/clinics.ts';import {FALLBACK_TAXONOMY,serviceCategoriesApi,categoriesFor} from '#lib/api/service-categories.ts';import {apiMessage} from '#lib/admin/scheduling.ts';import type {MedicalFacility,MedicalFacilityCreate,FacilityType,PaymentType} from '#lib/types/clinic.ts';
 let {open=$bindable(false),clinic=null,onSaved}:{open?:boolean;clinic?:MedicalFacility|null;onSaved:(f:MedicalFacility)=>void}=$props();
 const days=[['monday','週一'],['tuesday','週二'],['wednesday','週三'],['thursday','週四'],['friday','週五'],['saturday','週六'],['sunday','週日']];
 let name=$state(''),phone=$state(''),address=$state(''),description=$state(''),latitude=$state<number|undefined>(),longitude=$state<number|undefined>(),type=$state<FacilityType>('healthcare'),payment=$state<PaymentType>('nhi'),categories=$state<string[]>([]),hoursEnabled=$state(true),active=$state(true),phoneBooking=$state(false),showSchedule=$state(true),duration=$state(30),hours=$state<{day:string;label:string;enabled:boolean;open:string;close:string;breaks:{start:string;end:string}[]}[]>([]),logo=$state<string|null>(null),busy=$state(false),error=$state(''),message=$state(''),tax=$state(FALLBACK_TAXONOMY);
 const clinicKey=$derived(clinic?.id??'new');
 $effect(()=>{if(!open)return;const key=clinicKey;untrack(()=>{void key;const c=clinic;name=c?.name??'';phone=c?.phone??'';address=c?.address??'';description=c?.description??'';latitude=c?.latitude??undefined;longitude=c?.longitude??undefined;type=c?.facility_type??'healthcare';payment=c?.payment_type??'nhi';categories=[...(c?.service_categories??[])];active=c?.is_active??true;phoneBooking=c?.phone_booking_enabled??false;showSchedule=c?.show_schedule??true;duration=c?.slot_duration??30;hoursEnabled=c?!!c.business_hours&&Object.keys(c.business_hours).length>0:true;logo=c?.logo_url??null;error='';message='';hours=days.map(([day,label],i)=>{const h=c?.business_hours?.[day];return{day,label,enabled:c?.business_hours!=null?!!h:i<6,open:h?.open??'09:00',close:h?.close??(i===5?'12:00':'18:00'),breaks:h?.breaks?.map(b=>({...b}))??[]};});void serviceCategoriesApi.get().then(v=>tax=v);});});
 function changeType(){categories=[];payment=type==='healthcare'?(clinic?.payment_type??'nhi'):'self_pay';}
 async function upload(e:Event){const input=e.currentTarget as HTMLInputElement,file=input.files?.[0];if(!file||!clinic)return;busy=true;error='';try{const updated=await adminClinicsApi.uploadLogo(clinic.id,file);logo=updated.logo_url;onSaved(updated);message='Logo 已更新';}catch(e){error=apiMessage(e,'Logo 上傳失敗');}finally{busy=false;input.value='';}}
 async function removeLogo(){if(!clinic)return;busy=true;error='';try{const updated=await adminClinicsApi.deleteLogo(clinic.id);logo=null;onSaved(updated);message='Logo 已移除';}catch(e){error=apiMessage(e,'無法移除 Logo');}finally{busy=false;}}
 async function save(e:SubmitEvent){e.preventDefault();error='';if(hoursEnabled&&!hours.some(h=>h.enabled)){error='請至少選擇一個營業日；如暫停接待，請停用院所。';return;}for(const h of hours.filter(h=>hoursEnabled&&h.enabled)){if(h.open>=h.close||h.breaks.some(b=>!b.start||!b.end||b.start>=b.end||b.start<h.open||b.end>h.close)){error=h.label+'的營業或休息時間不正確';return;}const sorted=[...h.breaks].sort((a,b)=>a.start.localeCompare(b.start));if(sorted.some((b,i)=>i>0&&b.start<sorted[i-1].end)){error=h.label+'的休息時間重疊';return;}}
 const data:MedicalFacilityCreate={name:name.trim(),phone:phone.trim(),address:address.trim(),description:description.trim(),latitude:latitude??null,longitude:longitude??null,facility_type:type,payment_type:payment,service_categories:categories,business_hours:Object.fromEntries(hours.filter(h=>hoursEnabled&&h.enabled).map(h=>[h.day,{open:h.open,close:h.close,...(h.breaks.length?{breaks:h.breaks}: {})}])),slot_duration:duration,phone_booking_enabled:phoneBooking,show_schedule:showSchedule};busy=true;try{const updated=clinic?await adminClinicsApi.update(clinic.id,{...data,is_active:active}):await adminClinicsApi.create(data);onSaved(updated);open=false;}catch(e){error=apiMessage(e,'院所儲存失敗，請保留表單並重試');}finally{busy=false;}}
</script>
<Modal bind:open title={clinic?'編輯院所':'新增院所'} description="設定公開資訊、服務類型與可預約營業時間。" {busy}><form onsubmit={save} class="space-y-6"><Feedback {error} {message}/><fieldset disabled={busy} class="space-y-4"><legend>基本資訊</legend>{#if clinic}<div class="flex flex-wrap items-center gap-3">{#if logo}<img src={logo} alt="院所 Logo" class="size-20 rounded-xl border object-contain"/>{/if}<label>上傳 Logo<input type="file" accept="image/jpeg,image/png,image/webp" onchange={upload}/></label>{#if logo}<Button variant="outline" onclick={removeLogo}>移除 Logo</Button>{/if}</div>{:else}<p class="text-sm text-muted-foreground">儲存院所後即可上傳 Logo。</p>{/if}<label>院所名稱<input bind:value={name} required maxlength="100"/></label><div class="grid gap-4 sm:grid-cols-2"><label>電話<input type="tel" bind:value={phone}/></label><label>服務類型<select aria-label="服務類型" bind:value={type} onchange={changeType}>{#each tax.facility_types as t (t.value)}<option value={t.value}>{t.label}</option>{/each}</select></label></div><label>地址<input bind:value={address}/></label><label>院所介紹<textarea bind:value={description} maxlength="2000"></textarea></label><div class="grid grid-cols-2 gap-4"><label>緯度<input type="number" step="any" min="-90" max="90" bind:value={latitude}/></label><label>經度<input type="number" step="any" min="-180" max="180" bind:value={longitude}/></label></div><label>付款方式<select aria-label="付款方式" bind:value={payment}>{#each tax.payment_types as p (p.value)}<option value={p.value} disabled={type!=='healthcare'&&p.value!=='self_pay'}>{p.label}</option>{/each}</select></label><fieldset><legend>服務分類</legend><div class="flex flex-wrap gap-4">{#each categoriesFor(tax,type) as c (c.code)}<label><input type="checkbox" bind:group={categories} value={c.code}/>{c.label}</label>{/each}</div></fieldset><div class="flex flex-wrap gap-4">{#if clinic}<label><input type="checkbox" bind:checked={active}/>院所啟用</label>{/if}<label><input type="checkbox" bind:checked={phoneBooking}/>開放電話預約入口</label>{#if clinic}<label><input type="checkbox" bind:checked={showSchedule}/>顯示門診時刻表</label>{/if}</div></fieldset><fieldset disabled={busy} class="space-y-4"><legend>營業時間與預約</legend><label><input type="checkbox" bind:checked={hoursEnabled}/>設定固定營業時間</label><p class="text-xs text-muted-foreground">未設定固定時間時，依人員班表提供預約；暫停營業請停用院所。</p><label>預約間隔<select aria-label="預約間隔" bind:value={duration}>{#each [3,5,15,30,60] as m (m)}<option value={m}>{m} 分鐘</option>{/each}</select></label>{#if hoursEnabled}{#each hours as h (h.day)}<div class="space-y-3 rounded-xl border p-3"><label><input type="checkbox" bind:checked={h.enabled}/>{h.label}營業</label>{#if h.enabled}<div class="grid grid-cols-2 gap-3"><label>{h.label}開始<input type="time" bind:value={h.open} required/></label><label>{h.label}結束<input type="time" bind:value={h.close} required/></label></div>{#each h.breaks as b,i (i)}<div class="grid grid-cols-[1fr_1fr_auto] items-end gap-2"><label>休息開始<input type="time" bind:value={b.start} required/></label><label>休息結束<input type="time" bind:value={b.end} required/></label><Button variant="ghost" onclick={()=>h.breaks.splice(i,1)}>移除</Button></div>{/each}{#if h.breaks.length<2}<Button size="sm" variant="outline" onclick={()=>h.breaks.push({start:'12:00',end:'13:00'})}>新增{h.label}休息時段</Button>{/if}{/if}</div>{/each}{/if}</fieldset><div class="sticky bottom-0 flex justify-end gap-2 border-t bg-background py-3"><Button variant="outline" disabled={busy} onclick={()=>open=false}>取消</Button><Button type="submit" disabled={busy}>{busy?'儲存中…':'儲存院所'}</Button></div></form></Modal>
